/**
 * defines the type of a checklist item
 */
export type TnsChecklistItemType = 'TEXT_FIELD' | 'REQUIRED_FIELD' | 'OPTIONAL_FIELD' | 'INCLUDED_CHECKLIST' | 'REQUIRED_TEXT_FIELD' | 'OPTIONAL_TEXT_FIELD' | 'REQUIRED_MULTISELECT' | 'OPTIONAL_MULTISELECT' | 'EVENT_CONTAINER' | 'APPROVAL_PROCESS';

/**
 * describes the "state" of a checklist item, i.e. if it's checked
 */
export type TnsChecklistAction = {
  /**
   * 1 = checked / 0 = not checked
   */
  value?: number;
  /**
   * date, when the action took place
   */
  date?: number;
  /**
   * id of the user who checked this field
   */
  userId?: number;
  /**
   * if a support was created, while this item was check, the id is given here (which contains the sevice text for this item)
   */
  supportId?: number;
};

/**
 * represents an item in a checklist
 */
export type TnsChecklistItem = {
  /**
   * id of the item
   */
  id?: number;
  /**
   * id of the checklist, which the item is contained in
   */
  checklistId?: number;
  type?: TnsChecklistItemType;
  /**
   * headinh / title of the checklist item
   */
  heading?: string;
  /**
   * description / text of the checklist item
   */
  description?: string;
  /**
   * true if this is the first item of a checklist
   */
  entryPoint?: boolean;
  /**
   * id of the "next" field in the process chain
   */
  nextItemId?: number;
  /**
   * text which is used when creating a support
   */
  serviceText?: string;
  /**
   * true if thes field is hidden
   */
  hidden?: boolean;
  action?: TnsChecklistAction;
  /**
   * if vars were used in teh text, these must be given in the "check" body to fill in the correct values / infos for checking the item
   */
  vars?: Array<TnsChecklistItemVar>;
};

/**
 * detailled infos for the checklist, with all values (checked items, history, vars atc.)
 */
export type TnsChecklistWithProcessInfos = TnsChecklist & {
  items?: Array<TnsChecklistItem>;
};

/**
 * infos required for checking an item in a checklist
 */
export type TnsChecklistItemCheckBody = {
  /**
   * id of the checlist item that will be checked
   */
  itemId?: number;
  /**
   * id of the checklist which this item is in
   */
  checklistId?: number;
  /**
   * if the item is part of an "included" checklist, you must specify the "main" checklist as well
   */
  mainChecklistId?: number;
  /**
   * linktype of the assignment (i.e. 11 for ticket)
   */
  linkTypeId?: number;
  /**
   * link id of the assignment (if assigned to a ticket then the ticket id goes here)
   */
  linkId?: number;
  /**
   * 1 = check / 0 = uncheck
   */
  value?: number;
  /**
   * if an multiselect option is checked, give the multiselect option id here
   */
  multiSelectId?: number;
  /**
   * if vars are needed for checking this field, then give these here
   */
  vars?: {
    [key: string]: string;
  };
};

/**
 * determines which filter for "internal support" shall be used
 */
export type TnsInternalSupportFilter = 'ALL' | 'ONLY_INTERNAL' | 'ONLY_EXTERNAL';

/**
 * Enum representing the logic linking of certain ids (AND / NOT / OR)
 */
export type LogicOperatorType = 'AND' | 'OR' | 'NOT';

/**
 * determines which filter for "discounted" supports shall be used
 */
export type TnsDiscountedSupportTypeFilter = 'ALL' | 'ONLY_WITH_ADDITION' | 'ONLY_WITH_DISCOUNT' | 'ONLY_WITH_ZERO_PERCENT';

/**
 * determines wether supports from open tickets shall be fecthed or not
 */
export type TnsOpenTicketsFilter = 'SUPPORTS_FROM_ALL_TICKETS' | 'SUPPORTS_FROM_OPEN_TICKETS' | 'SUPPORTS_FROM_CLOSED_TICKETS' | 'ALL_SUPPORTS_BUT_OPEN_TICKETS';

/**
 * determines wether supports from tasks shall be fetched as well
 */
export type TnsSupportTaskFilter = 'ONLY_TASK_SUPPORTS' | 'NO_TASK_SUPPORTS';

/**
 * object containing support list query parameters.
 *
 * When querying support with these parameters, you can only use the filter settings you need (You don't have to specify all)
 *
 */
export type TnsSupportConfiguration = {
  timeframe?: TnsTimeframe;
  /**
   * show only supports from these support locations
   */
  supportLocations?: Array<TnsSupportLocation>;
  /**
   * show only supports with these support icon types
   */
  supportIconTypes?: Array<TnsSupportIconType>;
  /**
   * show only supports from this companies (ids)
   */
  companies?: Array<number>;
  /**
   * filter for emmployees (technician) ids
   */
  employees?: Array<number>;
  internalSupport?: TnsInternalSupportFilter;
  /**
   * show supports from these company categories (ids)
   */
  companyCategories?: Array<number>;
  companyCategoriesMatchType?: LogicOperatorType;
  /**
   * true, if supports from the own company shall be excluded
   */
  excludeOwnCompany?: boolean;
  /**
   * filter for a certain invoice (erp) number
   */
  invoiceNumber?: string;
  /**
   * true if external employees shall be excluded
   */
  excludeExternalEmployees?: boolean;
  discountedSupports?: TnsDiscountedSupportTypeFilter;
  /**
   * show supports from these "Not charged reasons" only
   */
  notChargedReasons?: Array<number>;
  /**
   * show supports from these departments only
   */
  departmentFilter?: Array<number>;
  /**
   * show supports from these ticket types
   */
  ticketTypes?: Array<number>;
  /**
   * show supports from these ticket (ids) only
   */
  tickets?: Array<number>;
  /**
   * show supports from these ticket phases only
   */
  ticketPhases?: Array<number>;
  /**
   * show supports from these link types only
   */
  linkTypes?: Array<number>;
  /**
   * show supports from these support types only
   */
  supportTypes?: Array<number>;
  /**
   * if true, all sub-ticket supports will be included as well (when displaying support from projects)
   */
  includeSubTickets?: boolean;
  /**
   * show supports from these planning types only
   */
  planningTypes?: Array<TnsPlanningType>;
  /**
   * if filtering for support containing a given text, you can specify the text filter here
   */
  textFilter?: string;
  /**
   * true if relation supports shall fe fecthed as well (when specifying company filter)
   */
  useRelations?: boolean;
  openTickets?: TnsOpenTicketsFilter;
  taskFilter?: TnsSupportTaskFilter;
  /**
   * show supports from these support "import types" only
   */
  importTypes?: Array<TnsPlanningType>;
  /**
   * show supports from these contracts (ids)
   */
  contracts?: Array<number>;
  /**
   * true if recurrence rules (appointments) shall be fetched as well
   */
  fetchRecurring?: boolean;
};

/**
 * state of the voucher / erp export for a support
 */
export type TnsVoucherExportState = 'NONE' | 'WAITING_FOR_VOUCHER_NR' | 'VOUCHER_NR_WAS_TRANSMITTED';

/**
 * Optional map of meta information for a support, present only when the support carries such data (e.g. appointments synced from Outlook). Individual keys are omitted when not set.
 */
export type TnsSupportMetaInfos = {
  /**
   * origin of a synced appointment (e.g. "TANSS", "OUTLOOK")
   */
  SYNC_ORIGIN?: string;
  /**
   * sync group / correlation id of the appointment
   */
  SYNC_GROUP?: string;
  /**
   * status of the synced appointment (e.g. "ACCEPTED", "REQUESTED", "CANCELED")
   */
  SYNC_APPOINTMENT_STATUS?: string;
  /**
   * comma separated list of participant e-mail addresses
   */
  OUTLOOK_PARTICIPANTS?: string;
  /**
   * Microsoft Teams meeting url of the synced appointment
   */
  TEAMS_URL?: string;
  /**
   * "1" if the support text was changed after the sync
   */
  TEXT_WAS_CHANGED?: string;
};

/**
 * A single support entry as returned by `PUT /api/v1/supports/list`. This is deliberately NOT the full `TnsSupport` model: the list endpoint serialises a reduced, permission-dependent projection (backend: `TnsSupportListService.getListFilters()` + `TnsSupportFilter`). Fields that belong only to the detail view (`GET /api/v1/supports/{id}`) or the create/update model are NOT part of the list response, e.g. `driveType`, the drive `*Charged` flags, `taskId`, `zoneId`, `orderedViaId`, `softwareLicenseId`, `importType`, `installationFeeDriveMode`, `teamsUrl`, `serviceLocationId`, `separateBilling` and `reasonNotChargedText`. In addition, single fields are omitted depending on the caller's rights, licensed modules and configuration, e.g. `hourlyRate` (right VIEW_HOURLY_RATE), `voucherId` (VIEW_VOUCHERS), `internal` / `textIntern` (may-see-internal-entities), `accountingTypeId` / `createdEmployeeId` (customer logins), `duration*` (SHOW_SUPPORT_DURATION_FOR_CUSTOMER), `ticketId` / `externalTicketId` (module TICKET / config TICKET_EXTERNAL_ID_ACTIVATED), `contractId` (module MAINTENANCE).
 */
export type TnsSupportList = {
  /**
   * id of this support
   */
  id?: number;
  /**
   * id of the connected ticket (omitted if module TICKET is not licensed)
   */
  ticketId?: number;
  /**
   * link type of the assignment
   */
  linkTypeId?: number;
  /**
   * id of the assignment
   */
  linkId?: number;
  /**
   * id of the company for this support
   */
  companyId?: number;
  /**
   * id of the employee who has done this support
   */
  employeeId?: number;
  /**
   * id of the employee who created this support (omitted for customer logins)
   */
  createdEmployeeId?: number;
  /**
   * id of the department assigned to this support
   */
  departmentId?: number;
  /**
   * id of the cost center
   */
  costCenterId?: number;
  /**
   * id of the support type
   */
  typeId?: number;
  /**
   * id of the accounting type used for this support (omitted for customers lacking the right)
   */
  accountingTypeId?: number;
  /**
   * id of the maintenance contract (omitted if module MAINTENANCE is not licensed)
   */
  contractId?: number;
  /**
   * id of the car (if a car is used)
   */
  carId?: number;
  /**
   * beginning of the support
   */
  date?: number;
  /**
   * duration of the service in minutes (omitted for customers lacking SHOW_SUPPORT_DURATION_FOR_CUSTOMER)
   */
  duration?: number;
  /**
   * duration which is not charged (in minutes)
   */
  durationNotCharged?: number;
  /**
   * duration (in minutes) of the approach (drive)
   */
  durationApproach?: number;
  /**
   * duration (in minutes) of the departure (drive)
   */
  durationDeparture?: number;
  /**
   * duration of the pause (in minutes)
   */
  durationBreak?: number;
  /**
   * timestamp when the pause starts (0 if no pause is given)
   */
  startBreak?: number;
  /**
   * km of the approach (drive)
   */
  kmApproach?: number;
  /**
   * km of the departure (drive)
   */
  kmDeparture?: number;
  location?: TnsSupportLocation;
  planningType?: TnsPlanningType;
  supportIconType?: TnsSupportIconType;
  clearanceStatus?: TnsSupportClearanceStatus;
  export?: TnsVoucherExportState;
  /**
   * description / text for this support entry (may be truncated, see meta.properties.extras.truncateTextLength)
   */
  text?: string;
  /**
   * internal remarks (only present if the caller may see internal entities)
   */
  textIntern?: string;
  /**
   * erp number of the support (if entered)
   */
  erpNumber?: string;
  /**
   * external ticket number (only present with module TICKET and config TICKET_EXTERNAL_ID_ACTIVATED)
   */
  externalTicketId?: string;
  /**
   * whether the support was already booked
   */
  booked?: boolean;
  /**
   * if this support is marked as "internal" (only present if the caller may see internal entities)
   */
  internal?: boolean;
  /**
   * true if this support was created by a customer login
   */
  extern?: boolean;
  /**
   * true if this support was booked after consultation ("Rücksprache")
   */
  consultation?: boolean;
  /**
   * whether the support is billed as a fixed-price installation fee
   */
  installationFee?: boolean;
  /**
   * amount of the installation fee (only present for technicians/freelancers)
   */
  installationFeeAmount?: number;
  /**
   * id of the installation fee type
   */
  installationFeeTypeId?: number;
  /**
   * hourly rate for this support (only present with the right VIEW_HOURLY_RATE)
   */
  hourlyRate?: number;
  /**
   * percent that shall be applied
   */
  percent?: number;
  /**
   * id of the voucher this support was booked to (only present with the right VIEW_VOUCHERS)
   */
  voucherId?: number;
  /**
   * id of the "not charged reason" (if the support was completely not charged)
   */
  reasonNotChargedId?: number;
  /**
   * id of the "not charged reason" (if the support was partially not charged)
   */
  reasonPartialNotChargedId?: number;
  /**
   * id of the linked vacation request (0 if none)
   */
  vacationRequestId?: number;
  /**
   * link type of a related entity (0 if none)
   */
  relationshipLinkTypeId?: number;
  /**
   * link id of a related entity (0 if none)
   */
  relationshipLinkId?: number;
  /**
   * true if this support is a synced Outlook/TANSS2Ex appointment
   */
  outlook?: boolean;
  /**
   * title for outlook appointments
   */
  outlookTitle?: string;
  /**
   * location for outlook appointments
   */
  outlookLocation?: string;
  metaInfos?: TnsSupportMetaInfos;
  /**
   * tags assigned to the support (only present for technicians/freelancers)
   */
  tags?: Array<TnsTag>;
  /**
   * material booked on the support (present when material is fetched)
   */
  material?: Array<{
    [key: string]: unknown;
  }>;
};

