/**
 * a TANSS timer
 */
export type Timer = {
  id?: number;
  /**
   * id of the employee of this timer
   */
  employeeId?: number;
  /**
   * id of the company (otional)
   */
  companyId?: number;
  /**
   * a title for this timer
   */
  title?: string;
  /**
   * total duration (in seconds) for this timer
   */
  duration?: number;
  /**
   * (optional) if the timer was created for a callback, the id is given here
   */
  callbackId?: number;
  /**
   * (optional) if the timer was created for a ticket, the id is given here
   */
  ticketId?: number;
  /**
   * (optional) if the timer was created for a misc. assignment, the linkTypeId goes here
   */
  linkTypeId?: number;
  /**
   * (optional) if the timer was created for a misc. assignment, the linkId goes here
   */
  linkId?: number;
};

/**
 * Timers can have multiple fragments, meaning a start/stop timeframe.
 * Each fragment can have a note.
 * A timer is running if the last fragment has no stop time.
 * If the last fragment has a stop time, the timer is stopped.
 *
 */
export type TimerFragment = {
  /**
   * id of the timer id for this fragment
   */
  timerId?: number;
  /**
   * starting time of the fragment
   */
  startTime?: number;
  /**
   * end time of the fragment (if 0 means that the timer is still running)
   */
  stopTime?: number;
  /**
   * a note for this fragment.
   * You could for example make notes of things which are done in this fragment which should help generating the support for this timer
   *
   */
  note?: string;
};

/**
 * describes who "owns" this pc
 */
export type TnsDeviceOwnageType = 'OWN' | 'FOREIGN' | 'OWN_RENT' | 'FOREIGN_RENT';

/**
 * Describes a pc or server
 */
export type TnsPersonalComputer = {
  /**
   * id of the pc / server
   */
  id?: number;
  /**
   * inventory number
   */
  inventoryNumber?: string;
  /**
   * is this pc active or not ?
   */
  active?: boolean;
  /**
   * id of the company which this pc is assigned to
   */
  companyId?: number;
  /**
   * hostname
   */
  name?: string;
  /**
   * id of the responsible service technician
   */
  serviceTechnicianId?: number;
  /**
   * id of employee, which this pc is assigned to
   */
  employeeId?: number;
  /**
   * date when this pc was purchased
   */
  date?: number;
  /**
   * location / room of this pc
   */
  location?: string;
  /**
   * id of the manufacturer of this pc
   */
  manufacturerId?: number;
  /**
   * describes the "model" of the pc. This field often is used to describe the pc (mostly in lists)
   */
  model?: string;
  /**
   * serial number
   */
  serialNumber?: string;
  /**
   * id of the operating system
   */
  osId?: number;
  /**
   * a text field which contains infos about installed software
   */
  software?: string;
  /**
   * a text field which contains misc. infos / remarks about this pc
   */
  remark?: string;
  /**
   * if true, the remark will be shown as popup when this pc is selected in a support/ticket mask and the employee has the permission
   */
  showRemark?: boolean;
  /**
   * id of the mainboard manufacturer
   */
  mainboardManufacturerId?: number;
  /**
   * revision of the mainboard
   */
  mainboardManufacturerRevision?: string;
  /**
   * serial number of the mainboard
   */
  mainboardSerialNumber?: string;
  /**
   * infos about the bios
   */
  bios?: string;
  /**
   * release infos of the bios
   */
  biosRelease?: string;
  /**
   * id of the cpu manufacturer
   */
  cpuManufacturerId?: number;
  /**
   * id of the cpu type
   */
  cpuTypeId?: number;
  /**
   * frequency of the cpu (in MHz)
   */
  cpuFrequency?: number;
  /**
   * number of cpus
   */
  cpuNumber?: number;
  /**
   * serial number of the mouse
   */
  mouseSerialNumber?: string;
  /**
   * serial number of the keyboard
   */
  keyboadSerialNumber?: string;
  /**
   * true if this pc is a server
   */
  server?: boolean;
  /**
   * internal remarks of the pc (can contain passwords), which only is seen by technicians or freelancers with the given permission
   */
  internalRemark?: string;
  /**
   * infos about the billing number which this pc was purchased
   */
  billingNumber?: string;
  /**
   * article number of the pc
   */
  articleNumber?: string;
  /**
   * manufacturer number of this pc
   */
  manufacturerNumber?: string;
  /**
   * if this pc is a virtual host, then here the id of the host is given
   */
  hostId?: number;
  /**
   * purchase price of this pc
   */
  purchasePrice?: number;
  /**
   * selling price of this pc
   */
  sellingPrice?: number;
  ownageType?: TnsDeviceOwnageType;
  /**
   * id of the storage, the pc is contained in
   */
  storageId?: number;
  /**
   * TeamViewer id
   */
  teamviewerId?: string;
  /**
   * TeamViewer password
   */
  teamviewerPassword?: string;
  /**
   * AnyDesk id
   */
  anydeskId?: string;
  /**
   * AnyDesk password
   */
  anydeskPassword?: string;
  /**
   * reserved ram for this virtual host
   */
  reservedRam?: number;
  /**
   * reserved hard disk space reserved for this virtual host
   */
  reservedHardDisk?: number;
  /**
   * reserved cpu capacity reserved for this virtual host
   */
  reservedCpu?: number;
  /**
   * misc. description infos for this pc
   */
  description?: string;
};

/**
 * Information of network interface options (such as ip or mac address)
 */
export type TnsIpMacMinimum = {
  /**
   * ip address
   */
  ip?: string;
  /**
   * mac address
   */
  mac?: string;
  /**
   * remarks
   */
  remark?: string;
  /**
   * is this entry a dhcp assigned ip address?
   */
  dhcp?: boolean;
};

/**
 * determines, which "id" is meant by "assignmentId"
 */
export type TnsIpMacAssignmentType = 'PC' | 'PERIPHERY';

export type TnsIpMac = TnsIpMacMinimum & {
  /**
   * id of this network interface entry
   */
  id?: number;
  assignmentType?: TnsIpMacAssignmentType;
  /**
   * id of the assignment, which this entry is assigned to (i.e. id of the pc)
   */
  assignmentId?: number;
};

/**
 * defines a service assignment of an ip address to a service
 */
export type TnsIpMacServiceAssignmentOnlyServiceId = {
  /**
   * id of the service
   */
  serviceId?: number;
};

export type TnsIpMacWithServiceAssignments = TnsIpMac & {
  /**
   * if you define ip addresses, you can also give a list of service assignments which shall be assigned to this ip address
   */
  serviceAssignments?: Array<TnsIpMacServiceAssignmentOnlyServiceId>;
};

/**
 * Information of the guarantee or warranty of a device
 */
export type TnsGuarantee = {
  /**
   * link type id of the assignment
   */
  linkTypeId?: number;
  /**
   * link id of the assignment
   */
  linkId?: number;
  /**
   * date when this device was purchased
   */
  purchaseDate?: number;
  /**
   * number of months (device guarantee)
   */
  guaranteeMonth?: number;
  /**
   * date when the guarantee expires
   */
  guaranteeExpire?: number;
  /**
   * number of months (device warranty)
   */
  warrantyMonth?: number;
  /**
   * date when the warranty expires
   */
  warrantyExpire?: number;
  /**
   * Misc. remarks regarding the guarantee / warranty
   */
  remark?: string;
};

/**
 * Describes a pc or server with infos (ip address, guarantee)
 */
export type TnsPersonalComputerWithIpGuarantee = TnsPersonalComputer & {
  ips?: Array<TnsIpMacWithServiceAssignments>;
  guarantee?: TnsGuarantee;
};

/**
 * Defines the "type" of the service icon
 */
export type TnsServiceIconType = 'SERVICE' | 'TEAMVIEWER' | 'ANYDESK';

/**
 * Service icon which is shown when listing pcs or server.
 *
 * They are used to establish a connection to the device.
 *
 */
export type TnsServiceIcon = {
  type?: TnsServiceIconType;
  /**
   * name of the service
   */
  name?: string;
  /**
   * address which is used to establish the connection (mostly the ip address)
   */
  address?: string;
  /**
   * if the service has an "own" icon, here the name of the image is given
   */
  symbol?: string;
  /**
   * if the service has a special "call" (command line or url), the command is given
   */
  command?: string;
};

/**
 * Describes a pc component
 */
export type TnsComponent = {
  /**
   * id of the pc / server
   */
  id?: number;
  /**
   * inventory number of this component
   */
  inventoryNumber?: string;
  /**
   * id of the component type
   */
  componentTypeId?: number;
  /**
   * the component is built into this pc (0 if the component ist not attached to a pc)
   */
  pcId?: number;
  /**
   * if the component is built into a periphery, here the id is given
   */
  peripheryId?: number;
  /**
   * id of the components manufacturer
   */
  manufacturerId?: number;
  /**
   * type of the component. This is mostly used to "describe" the component in lists
   */
  type?: string;
  /**
   * serial number of the component
   */
  serialNumber?: string;
  /**
   * capcity (in megbytes), which is used to determine the size of ram or HDDs
   */
  megabytes?: number;
  /**
   * id of the HDD type
   */
  hddTypeId?: number;
  /**
   * SCSI id
   */
  scsiId?: string;
  /**
   * if true, the component is "onboard"
   */
  onBoard?: boolean;
  /**
   * id of the company, which this component is assigned to. Only relevant if the component is not built into a pc!
   */
  companyId?: number;
  /**
   * remarks for this component
   */
  remark?: string;
  /**
   * true, if the component is active
   */
  active?: boolean;
  /**
   * date when the component was purchased (or entered into the system)
   */
  date?: number;
  /**
   * infos about the billing number which this component was purchased
   */
  billingNumber?: string;
  /**
   * article number of the component
   */
  articleNumber?: string;
  /**
   * id of the storage, the component is contained in
   */
  storageId?: number;
  /**
   * purchase price of this component
   */
  purchasePrice?: number;
  /**
   * selling price of this component
   */
  sellingPrice?: number;
  /**
   * misc. description infos for this component
   */
  description?: string;
};

/**
 * infos regarding "additional" fields in a periphery
 */
export type TnsPeripheryFieldInfo = {
  /**
   * id of the additional field
   */
  additionalFieldId?: number;
  /**
   * title name for the field
   */
  title?: string;
  /**
   * value for this additional field
   */
  value?: string;
};

/**
 * Describes a periphery
 */
export type TnsPeriphery = {
  /**
   * id of the periphery
   */
  id?: number;
  /**
   * id of the assigned company
   */
  companyId?: number;
  /**
   * date when the device was purchased (or entered into the system)
   */
  date?: number;
  /**
   * id of the periphery type
   */
  peripheryTypeId?: number;
  /**
   * id of the device manufacturer
   */
  manufacturerId?: number;
  /**
   * type of the periphery. This is mostly used to "describe" the periphery in lists
   */
  type?: string;
  /**
   * location / room of this device
   */
  location?: string;
  /**
   * remarks for this component
   */
  remark?: string;
  /**
   * internal remarks of the device (can contain passwords), which only is seen by technicians or freelancers with the given permission
   */
  internalRemark?: string;
  /**
   * serial number of the device
   */
  serialNumber?: string;
  /**
   * inventory number of this device
   */
  inventoryNumber?: string;
  /**
   * infos of the version of this device
   */
  version?: string;
  /**
   * true, if the device is active
   */
  active?: boolean;
  /**
   * id of the assigned employee
   */
  employeeId?: number;
  /**
   * if the device is built into this pc, a pc id is given here
   */
  pcId?: number;
  /**
   * infos about the billing number which this component was purchased
   */
  billingNumber?: string;
  /**
   * article number of the component
   */
  articleNumber?: string;
  /**
   * id of the storage, the component is contained in
   */
  storageId?: number;
  /**
   * purchase price of this component
   */
  purchasePrice?: number;
  /**
   * selling price of this device
   */
  sellingPrice?: number;
  ownageType?: TnsDeviceOwnageType;
  /**
   * hostname
   */
  name?: string;
  /**
   * misc. description infos for this device
   */
  description?: string;
  /**
   * manufacturer number of this device
   */
  manufacturerNumber?: string;
  fields?: Array<TnsPeripheryFieldInfo>;
};

/**
 * Describes an assignment of an entity to another entity
 */
export type TnsAssignment = {
  /**
   * link type of the assignment (1=PC, 2=Company, etc.)
   */
  linkTypeId?: number;
  /**
   * id of the linked entity (the entity to which the assignment is linked)
   */
  linkId?: number;
};

/**
 * Describes a software license
 */
export type TnsSoftwarelicense = {
  /**
   * id of the software license
   */
  id?: number;
  /**
   * company id of the software license
   */
  companyId?: number;
  /**
   * misc. infos of for this software license
   */
  remark?: string;
  /**
   * internal remarks of the license (can contain passwords), which only is seen by technicians or freelancers with the given permission
   */
  internalRemark?: string;
  /**
   * serial number
   */
  serialNumber?: string;
  /**
   * inventory number
   */
  inventoryNumber?: string;
  /**
   * id of the sofware license type
   */
  softwarelicenseTypeId?: number;
  /**
   * date when the software license will expire
   */
  expirationDate?: number;
  /**
   * if true, the license must be renewed upon expiring and therefore needs further "attention"
   */
  renew?: boolean;
  /**
   * starting date for this software license
   */
  date?: number;
  /**
   * maximum number of installations
   */
  maxNumberOfInstall?: number;
  /**
   * number of volumes (i.e. cds)
   */
  numberOfVolumes?: number;
  /**
   * true if the software license is still active
   */
  active?: boolean;
  /**
   * id of employee which uses this software license
   */
  employeeId?: number;
  /**
   * article number of the component
   */
  articleNumber?: string;
  /**
   * price which is used in maintenace contracts
   */
  contractPrice?: number;
  /**
   * assignments of this software license to other entities
   */
  assignments?: Array<TnsAssignment>;
};

/**
 * Describes a pc or server with all "attached" infos
 */
export type TnsPersonalComputerWithDetails = TnsPersonalComputerWithIpGuarantee & {
  serviceIcons?: Array<TnsServiceIcon>;
  /**
   * infos about components which are built into this pc
   */
  components?: Array<TnsComponent>;
  /**
   * infos about devices which are linked to this pc
   */
  devices?: Array<TnsPeriphery>;
  /**
   * infos about software licenses which are used by this pc
   */
  softwarelicenses?: Array<TnsSoftwarelicense>;
};

/**
 * filter settings for branches
 */
export type TnsBranchFilterType = 'COMPANY_ONLY' | 'BRANCHES_ONLY' | 'COMPANY_AND_BRANCHES' | 'SPECIFIC_BRANCH';

/**
 * filter settings for "active" state of the device
 */
export type TnsActiveFilterType = 'ACTIVE_ONLY' | 'INACTIVE_ONLY' | 'ACTIVE_AND_INACTIVE';

/**
 * Parameters which are used to query for pcs when displaying a list of pcs/servers
 */
export type TnsDeviceBaseConfiguration = {
  /**
   * show only entries of this company
   */
  companyId?: number;
  branches?: TnsBranchFilterType;
  active?: TnsActiveFilterType;
};

/**
 * filter settings for the "server" state
 */
export type TnsServerFilterType = 'PCS_ONLY' | 'SERVERS_ONLY' | 'SERVERS_AND_PCS';

export type TnsPersonalComputerConfiguration = TnsDeviceBaseConfiguration & {
  /**
   * show only there os ids
   */
  osIds?: Array<number>;
  servers?: TnsServerFilterType;
};

/**
 * Describes a periphery with all "ip" infos
 */
export type TnsPeripheryWithIp = TnsPeriphery & {
  ips?: Array<TnsIpMacWithServiceAssignments>;
};

/**
 * Describes a periphery with all "attached" infos
 */
export type TnsPeripheryWithIpGuarantee = TnsPeripheryWithIp & {
  guarantee?: TnsGuarantee;
};

export type TnsPeripheryConfiguration = TnsDeviceBaseConfiguration & {
  /**
   * id of the periphery type to be filtered
   */
  peripheryTypeId?: number;
};

/**
 * Periphery type
 */
export type TnsPeripheryType = {
  /**
   * id of the periphery type
   */
  id?: number;
  /**
   * name of the periphery type
   */
  name?: string;
  /**
   * icon used when displaying peripheries of this type
   */
  image?: string;
};

/**
 * filter settings for "built in" state of the component (i.e. only built into pcs, periphery)
 */
export type TnsComponentBuiltInFilterType = 'NOT_BUILT_IN_COMPONENTS' | 'COMPONENTS_IN_PCS' | 'COMPONENTS_IN_PERIPHERIES';

export type TnsComponentConfiguration = TnsDeviceBaseConfiguration & {
  /**
   * id of the component type to be filtered
   */
  componentTypeId?: number;
  /**
   * if only components of a given pc shall be displayed
   */
  pcId?: number;
  /**
   * if only components of a given periphery shall be displayed
   */
  peripheryId?: number;
  builtInFilter?: TnsComponentBuiltInFilterType;
};

/**
 * Component type
 */
export type TnsComponentType = {
  /**
   * id of the component type
   */
  id?: number;
  /**
   * name of the component type
   */
  type?: string;
  /**
   * short name of the component type
   */
  shortName?: string;
  /**
   * if false, this type won't be shown in the select field (meaning its an inactive type)
   */
  shown?: boolean;
};

/**
 * object representing an employee
 */
export type Employee = {
  id?: number;
  /**
   * full name of the employee
   */
  name?: string;
  /**
   * first name of the employee
   */
  firstName?: string;
  /**
   * last name of the employee
   */
  lastName?: string;
  /**
   * id of the salutation for this employee
   */
  salutationId?: number;
  /**
   * id of the department which tis employee is assigned to
   */
  departmentId?: number;
  /**
   * location / room of the employee
   */
  room?: string;
  /**
   * main telephone number
   */
  telephoneNumber?: string;
  /**
   * e-Mail address
   */
  emailAddress?: string;
  /**
   * if this employee is assigned to a specific car, the id goes here
   */
  carId?: number;
  /**
   * mobile telephone number
   */
  mobilePhone?: string;
  /**
   * initials for this employee
   */
  initials?: string;
  /**
   * working hour model for this employee
   */
  workingHourModelId?: number;
  /**
   * id of the accounting type for this employee
   */
  accountingTypeId?: number;
  /**
   * private telephone number
   */
  privatePhoneNumber?: string;
  /**
   * true if the employee is active
   */
  active?: boolean;
  erpNumber?: string;
  /**
   * fax number
   */
  personalFaxNumber?: string;
  /**
   * role for this employee
   */
  role?: string;
  /**
   * if the employee uses a title, the id goes here
   */
  titleId?: number;
  /**
   * language which this employee uses
   */
  language?: string;
  /**
   * second telephone number
   */
  telephoneNumberTwo?: string;
  /**
   * second mobile telephone number
   */
  mobileNumberTwo?: string;
  /**
   * true, if the user has a "restricted" user license (if he/she is from the own company). restricted user licenses won't use a user license
   */
  restrictedUserLicense?: boolean;
  /**
   * birthday in the format "YYYY-MM-DD"
   */
  birthday?: string;
};

/**
 * Company object to be saved.
 */
export type CompanyPost = CompanyDetail & {
  /**
   * defines if this company is a "personal customer" - meaning that company and employee are the same person
   */
  personalCustomer?: boolean;
  personalCustomerEmployee?: Employee;
};

/**
 * Enum representing the "link type" of an assignment. The id is given in the field "linkId"
 */
export type TnsLinkType = 'PC' | 'COMPANY' | 'EMPLOYEE' | 'PERIPHERY' | 'COMPONENT' | 'SOFTWARELICENSE' | 'SUPPORT' | 'VOUCHER' | 'DOCUMENT' | 'DOCUMENT_S2T' | 'TICKET' | 'KNOWLEDGE_BASE' | 'PERMISSION' | 'PERMISSION_PACKAGE' | 'GROUP' | 'CALLBACK' | 'CONSULTATION' | 'SLA' | 'CONTRACT' | 'PREPAID_PURCHASE' | 'EVENT' | 'FILE_LINKS' | 'BIRTHDAY' | 'DOMAIN' | 'TEAMVIEWER' | 'REMOTE_SUPPORT' | 'DOCUSNAP' | 'MATERIAL' | 'CHAT' | 'TODO' | 'DOCUSNAP_SNMP' | 'VACATION_REQUEST' | 'TICKET_BOARD_PANEL' | 'DEPARTMENT' | 'COMPANY_TYPE' | 'TICKET_TYPE' | 'MAIL' | 'OFFER' | 'TICKET_STATE' | 'OVERTIME_ADDITIONAL_CHARGE' | 'CHECKLIST';

/**
 * defines the filter for the event rule list
 */
export type TnsTanssEventRuleConfiguration = {
  linkType?: TnsLinkType;
  /**
   * ids of the assignment to be filtered
   */
  linkIds?: Array<number>;
};

/**
 * Defines an assignment from a TANSS event rule to an assignment (i.e. Ticket Board Panel)
 */
export type TnsTanssEventRuleAssignment = {
  linkType?: TnsLinkType;
  /**
   * id of the assignment
   */
  linkId?: number;
};

/**
 * defines which action shall be executed
 */
export type TnsTanssEventRuleActionType = 'WEBHOOK';

/**
 * defines the parameters for the action
 */
export type TnsTanssEventRuleActionParams = {
  /**
   * defines the url a webhook url will be sent to (actionType WEBHOOK)
   */
  url?: string;
  /**
   * defines the http method for a webhook notification (actionType WEBHOOK)
   */
  method?: string;
};

/**
 * Defines an assignment from a TANSS event rule to an assignment (i.e. Ticket Board Panel)
 */
export type TnsTanssEventRuleAction = {
  actionType?: TnsTanssEventRuleActionType;
  params?: TnsTanssEventRuleActionParams;
};

export type TnsTanssEventRule = {
  id?: number;
  /**
   * defines a "name" for the rule
   */
  name?: string;
  /**
   * true if the rule is active. If "false", rule won't trigger notifications
   */
  active?: boolean;
  /**
   * defines for which "assignments" a rule shall be triggered (currently only used for ticket board panels)
   */
  assignments?: Array<TnsTanssEventRuleAssignment>;
  /**
   * defines which actions will be triggered when executing the rule
   */
  actions?: Array<TnsTanssEventRuleAction>;
};

