export type TnsLinkTypeForSearch = 'PC' | 'EMPLOYEE' | 'CPU_TYPE' | 'MANUFACTURER' | 'OS';

/**
 * in which "sections" shall be searched
 */
export type TnsIdentifySearchSection = 'NAME' | 'EMAIL' | 'DOMAIN' | 'SEARCH';

